insert into matcha_articles (url, lang, prefecture_code, title, body, images, published_at, place, text_attribution, text_attribution_url)
values
(E'https://matcha-jp.com/cn/1336', E'zh-Hans', 1, E'【2019年版】北海道绝美红叶10景点，美到不想离开！', E'若是秋天要去北海道的话，那一定不能错过以壮大自然景色为背景的红叶风情！本文章会推荐能欣赏枫叶又能享受温泉、户外活动的北海道推荐10大枫叶景点。\n\n北海道是位在日本最北端，最大的一个县市。在丰富的自然环境中，有以新鲜海产为首的美味料理、让人为之醉心的夜景等等魅力，不论是日本各地还是全世界，都有许多人到访。\n\n若是要在秋天到访北海道的话，那么一定要欣赏一下在壮丽自然景色下造就出的枫红景色了！ 本篇文章除了有介绍枫红之外，也会介绍可以享受温泉、户外活动等等北海道的10个人气赏枫景点和往年的枫红时期。\n\n由于北海道的范围相当广，依据场所不同，枫红时期虽然有差异，但大多景点都是10月～11月上旬开始能赏枫叶。其中层云峡(そううんきょう)的枫红在日本境内可说是最早开始，大约在8月下旬左右就开始了。', E'["https://resources.matcha-jp.com/resize/720x2000/2018/07/10-58199.webp","https://resources.matcha-jp.com/resize/720x2000/2018/07/10-58201.webp","https://resources.matcha-jp.com/resize/720x2000/2018/07/10-58210.webp","https://resources.matcha-jp.com/resize/720x2000/2018/07/10-58208.webp"]'::jsonb, E'2018-10-10'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/23878', E'zh-Hans', 1, E'对于初学者来说！完美的北海道旅行规划指南', E'对于计划前往北海道旅行的人来说，这绝对是必看景点！针对初学者，详细讲解最佳季节、旅游景点、交通、美食和温泉。\n\n北海道不仅拥有大自然风光，其市区也同样充满魅力。这里也是美食的宝库，有新鲜的海鲜、味噌拉面，还有用浓郁的北海道牛奶制作的甜点。这里有许多活动可做，从漫步富良野的薰衣草田，到享受新雪谷世界上最好的粉雪，再到在温泉中放松身心。\n\n日本之旅的11 天札幌自助游让游客沉浸在北海道首府的丰富文化和美景中。此次旅行包括舒适的住宿、方便交通的 JR Pass 以及探索札幌啤酒博物馆和大通公园等主要景点的个性化行程，还可以选择添加荞麦面制作课程等独特的当地体验。\n\n1）滑雪和滑雪板季节。札幌冰雪节等冬季活动也在这里举办。北海道是滑雪天堂，在这里您可以享受世界上最好的粉雪。新雪谷和富良野等滑雪胜地吸引了来自世界各地的滑雪者和滑雪板爱好者。公共交通也很发达，即使是初学者也可以轻松前往滑雪胜地。', E'["https://resources.matcha-jp.com/resize/720x2000/2025/04/04-230270.webp","https://resources.matcha-jp.com/resize/720x2000/2025/03/28-229664.webp","https://resources.matcha-jp.com/resize/720x2000/2025/03/28-229665.webp","https://resources.matcha-jp.com/resize/720x2000/2025/04/04-230271.webp"]'::jsonb, E'2025-02-02'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/23164', E'zh-Hans', 1, E'非常适合滑雪后放松！北海道推荐的温泉', E'为您介绍北海道滑雪之旅中必去的10处温泉。我们将带您前往登别、定山溪、富良野等最适合肌肉恢复和放松的温泉地区。雪景露天浴池也不容错过！\n\n这里是北海道最著名的温泉胜地，可以享受硫磺泉、铁泉、镭泉等多种温泉。每种涌水都有不同的保健功效；硫磺泉对皮肤有好处，铁泉有促进血液循环的功效。温泉的发源地地狱谷也推荐观光。\n\n距札幌约1小时车程，滑雪结束后可直接前往。氯化钠温泉有助于维持体温和放松肌肉。被丰富的自然包围的风景也很吸引人。\n\n这个温泉度假村位于函馆附近，已有350多年的历史。它含有大量的钙和钠，对关节和肌肉疼痛有效。您可以在海边的露天浴池里边泡澡边欣赏冬日的海浪。', E'["https://resources.matcha-jp.com/resize/720x2000/2025/07/02-238018.webp"]'::jsonb, E'2024-12-14'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/4255', E'zh-Hans', 2, E'【2024年最新】构图里不再有人群！日本东北樱花景点15选', E'想来日本赏樱却又不想人挤人吗？日本东北地区也有许多绝美赏樱景点等着大家去探索，而且构图里不再有人群。本篇整理了2024东北樱花预测时间，以及东北六县的15个樱花景点给各位参考，想要了解东北樱花魅力的话，就继续看下去吧！\n\n东北六县由北到南分别为青森县、秋田县、岩手县、宫城县、山形县、福岛县。虽然位于日本本岛，但由于位于本岛最北端，纬度高仅次于北海道，因此日本东北樱花季也相较其他地区来得晚，樱花也比较慢才盛开。\n\n以下为各县市的满开预测日，以及东北樱花最佳观赏时期。(2024年3月28日更新）\n\n接下来就带大家来认识15个日本东北樱花景点，如果有看到喜欢的景点的话，千万不要犹豫，马上加入自己的东北赏樱清单吧！', E'["https://resources.matcha-jp.com/resize/720x2000/2020/01/07-94518.webp","https://resources.matcha-jp.com/resize/720x2000/2020/01/07-94519.webp","https://resources.matcha-jp.com/resize/720x2000/2024/03/28-175574.webp","https://resources.matcha-jp.com/resize/720x2000/2024/03/28-175575.webp"]'::jsonb, E'2017-04-12'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/5637', E'zh-Hans', 2, E'这间星巴克不一样！咖啡与历史华丽共演，日本星巴克六大分店推荐', E'日本星巴克的多样化与特色店铺一直是星巴克迷或旅客的朝圣名单，这次MATCHA小编整理了拥有浓浓在地味的日本星巴克分店，不管是世界遗产还是历史建筑，带你从一杯咖啡的时光中，感受地方限定魅力。\n\n懂得融合在地文化，发展出独特风情的日本星巴克，许多特色店铺一直是星巴克迷或旅客的朝圣名单，这次MATCHA小编整理了拥有浓浓在地味的日本星巴克分店，从一杯咖啡的时光中，感受地方限定魅力。\n\n位于宫岛上的世界遗产“严岛神社”旁，2017年11月新开幕，是日本目前唯一要乘船才能到达的分店。\n\n内部装潢也融入宫岛当地名产。楼梯转角间的咖啡豆大碗中，就放有宫岛代表性的“饭匙”（しゃもじ），是当地用来祈求好运的吉祥物。', E'["https://resources.matcha-jp.com/resize/720x2000/2018/01/11-45707.webp","https://resources.matcha-jp.com/resize/720x2000/2018/01/11-45708.webp","https://resources.matcha-jp.com/resize/720x2000/2018/01/11-45709.webp","https://resources.matcha-jp.com/resize/720x2000/2018/01/11-45710.webp"]'::jsonb, E'2019-03-20'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/5799', E'zh-Hans', 2, E'整个东北都是我的游乐园！用JR东日本周游券（东北地区）看尽东北四季', E'热爱东北的小编教你用JR东日本铁路周游券JR EAST PASS（东北地区）玩遍东北六县青森,秋田,岩手,宫城,福岛,山形县！票价与购买方式以及东北四季行程推荐、必去绝景路线通通在这里！\n\n问起MATCHA小编最喜欢日本那个地区？小编绝对会直接回答“东北”。“东北地区”是指位于日本本岛最北方的六个县市：青森、秋田、岩手、山形、宫城与福岛，因为此地区地形狭长，单趟交通时间与金钱都所费不赀，还好我们有JR PASS 东北地区，轻松玩遍东北不用愁！\n\nJR东日本铁路周游券（东北地区）简称“JR EAST PASS 东北地区”，通称“JR 东北 PASS”是由JR东日本针对观光客所发售的交通券，在发售日开始算起14天内，任选五天，可在东北六县的规定范围内无限次搭乘JR与相关列车，是非常划算的交通票券。可使用范围看这边\n\n售价：成人（12岁以上）20000日元，儿童（6~11岁） 10000日元。在海外（非日本）的地区前往日本前先购买则各便宜1000日币。', E'["https://resources.matcha-jp.com/resize/720x2000/2018/02/22-48817.webp","https://resources.matcha-jp.com/resize/720x2000/2018/02/22-48818.webp","https://resources.matcha-jp.com/resize/720x2000/2018/02/22-48848.webp","https://resources.matcha-jp.com/resize/720x2000/2018/02/22-48855.webp"]'::jsonb, E'2018-05-06'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/11280', E'zh-Hans', 3, E'【岩手】搭乘三陆铁道游港都宫古！感受“鱿鱼王子”与绝景的魅力', E'提起【三陆铁道谷湾线】，不少人都是从日剧《海女》认识这条沿途碧海蓝天、与壮丽奇岩景观相伴的铁路。而三陆铁道公司的所在地“宫古”，除了因这片特殊海岸地形拥有多处自然绝景如青之洞窟以外，也以丰富的渔获蕴藏量被誉为世界三大渔场之一，加上当地名人鱿鱼王子的热血宣传，让水产加工产品的美味与魅力发扬光大。\n\n自2013年播出，就深受观众喜爱的日剧《海女》，其剧中出现的岩手县【三陆铁道谷湾线】铁路，就位在宫古。铁道名称便是以岩手的三陆谷湾命名。\n\n311东日本大地震时，【三陆铁道】受到海啸侵袭而严重损坏，经过3年的不懈努力，在2014年3月全线修复完工。而在2019年由于受到台风重创，再次部分损毁，终于在2020年恢复全线通车。\n\n三陆铁道谷湾线行经三陆海岸，不时能从窗外眺望壮丽的海景，更是串连着各城市的交通动脉，对于当地居民和铁道迷来说，都是非常重要的铁路之一。 三陆铁道宫古站', E'["https://resources.matcha-jp.com/resize/720x2000/2022/07/24-128578.webp","https://resources.matcha-jp.com/resize/720x2000/2022/07/24-128579.webp","https://resources.matcha-jp.com/resize/720x2000/2022/08/17-129053.webp","https://resources.matcha-jp.com/resize/720x2000/2022/07/24-128582.webp"]'::jsonb, E'2022-09-06'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/7096', E'zh-Hans', 3, E'【东北】一生必去一次！奔驰白雪之中的4大铁道绝景！', E'冬天的绝景，怎能少了穿梭在无尽白雪中的铁道列车！4条绝景铁路分别位于东北3县内，使用“JR东日本铁路周游券(东北地区) east pass”就能制霸福岛只见线、岩手银河铁道釜石线、山形长井线等冬日铁道绝景！\n\n说到冬天的绝景，除了披上白雪外衣的银白大地外，在无尽白雪中穿梭的铁道列车也更让人震撼神往！不管是冲破皓皓白雪的奔驰、还是与雪花共舞的缓行，钢铁与白雪的结合，成就限定期间的绝景。这次就要为大家介绍东北大地上，不可不去的冬日铁道绝景！\n\n说到雪中铁道，绝对不能不提的就是“JR只见线”，拥有“世间最浪漫的铁道路线”之称，尤其是那由上往下俯视“只见川第一大桥”的山谷铁桥画面，稳坐白雪绝景铁道宝座。\n\n只见线班次少，一天仅不到8个班次，因此建议乘坐始发电车，从“会津若松站”前往“会津宫下站”约1个半小时，再转乘接送巴士前往“道の駅尾濑街道みしま宿”，旁边不远处就是只见线经典画面的拍摄地点。', E'["https://resources.matcha-jp.com/resize/720x2000/2019/02/24-71869.webp","https://resources.matcha-jp.com/resize/720x2000/2019/02/18-71561.webp","https://resources.matcha-jp.com/resize/720x2000/2019/02/19-71595.webp","https://resources.matcha-jp.com/resize/720x2000/2019/02/18-71562.webp"]'::jsonb, E'2019-02-28'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/15704', E'zh-Hans', 2, E'鲜美的海产宝库！东北和关东地区知名水产19选', E'日本的东北地区及关东的太平洋沿岸地区，受到洋流的影响，渔业发达，更是有着多处享誉世界的渔场。文中精选19款海产加工美食，从基础的干贝、鱿鱼、鲭鱼等各色限定美味，保证大家垂涎三尺，想要立刻购买。\n\n特别是以岩手县、宫城县和及青森县的太平洋一侧，收到三陆和金华山沿海洋流的影响，各类海产十分丰富，当然这些美味的海产在加工后也被销往日本各地及海外。三陆和金华山沿海地区是北方的寒流和南方的暖流交汇之处，各种鱼类聚集于此，因此被誉为世界三大渔场之一。\n\n此外，东京的近邻，关东地区的千叶县有着享誉日本的沙丁鱼捕获量的九十九里町，茨城县也有众多优良的渔场，无论是伊势龙虾、鲭鱼、沙丁鱼等多种海产均有不俗的捕捞量。 小编特别汇总东北及关东地区的丰富海产品，并按照地区为大家详细介绍。\n\n提到津轻海峡的品牌海产，不得不提的就是因受冷海水和强劲洋流的培育而成的“海峡鲑鱼”。养殖这种鱼难度极高，甚至需要长达30年才能稳定养殖，但现在已成为青森代表的品牌。', E'["https://resources.matcha-jp.com/resize/720x2000/2023/11/15-152416.webp","https://resources.matcha-jp.com/resize/720x2000/2022/08/01-128818.webp","https://resources.matcha-jp.com/resize/720x2000/2022/01/05-119338.webp","https://resources.matcha-jp.com/resize/720x2000/2020/12/17-110892.webp"]'::jsonb, E'2023-12-10'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/12250', E'zh-Hans', 3, E'【岩手】世界唯一的海胆牧场！来北三陆Factory品尝顶级海胆美味', E'拥有全球卓越的海胆培育技术、也是世界唯一的【海胆牧场®】坐落在日本东北地区的岩手洋野町的【北三陆Factory】，主要以饲育北紫海胆为主，生产包括带壳海胆、海胆抹酱等多种水产加工品，其奢华的美味受到高度评价，其创造出人与海洋共生的海胆饮食文化，同时也能让海洋永续发展。\n\n北三陆，包含岩手县的久慈市、洋野町、野田村、普代村4个自治体，为三陆海岸的一部分。北三陆地区拥有丰富的海洋资源，特别是海带和海胆等海藻类的收获量居多，加上杂食性海胆以天然海藻为食，让岩手的美味海胆在日本国产海胆渔获量中，仅次于北海道，成为排名第二的国产海胆知名产地。\n\n想要了解北三陆，建议可以到久慈地下水族科学馆【moguranpia】参观。这里是日本少见的以隧道建造的水族馆，还能观赏到这地区独有的南部潜水和海女的素潜技术（※）。\n\n此外还有水母区域、和同时担任【moguranpia】水族馆的加油团团长、鱼类专家鱼君先生个人捐赠的鱼类展示等，是一处寓教于乐的观光景点。 摩尔皮亚', E'["https://resources.matcha-jp.com/resize/720x2000/2023/07/15-141266.webp","https://resources.matcha-jp.com/resize/720x2000/2023/07/15-141251.webp","https://resources.matcha-jp.com/resize/720x2000/2023/07/18-141313.webp","https://resources.matcha-jp.com/resize/720x2000/2023/07/18-141326.webp"]'::jsonb, E'2023-09-20'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/22173', E'zh-Hans', 4, E'【宫城】栗駒山的枫叶最佳观赏时期是什么时候？赏枫看点及周边观光景点介绍！', E'东北地区代表性的红叶胜地——栗駒山。每到秋天，枫树、杜鹃和绣球等红叶将整个山头染成鲜艳的绚丽色彩，形成壮观全景。本文章将介绍栗駒山红叶的最佳观赏时期、赏枫看点以及周边的观光景点。\n\n位于宫城县、岩手县和秋田县交界的栗駒山是东北地区著名的红叶胜地。每到秋天，枫树、杜鹃和绣球等落叶树的红叶将整座山变成如火如荼的五彩缤纷的全景。\n\n此次将介绍栗駒山的红叶最佳观赏时期、看点及周边的观光景点。也提供了交通信息，欢迎大家查看。\n\n位于东北地区中央，南北延伸的奥羽山脉中段的栗駒山，是岩手、秋田、宫城三县交界处的标高1,626米的活火山。', E'["https://resources.matcha-jp.com/resize/720x2000/2024/10/20-203720.webp","https://resources.matcha-jp.com/resize/720x2000/2024/10/19-203654.webp","https://resources.matcha-jp.com/resize/720x2000/2024/10/19-203655.webp","https://resources.matcha-jp.com/resize/720x2000/2024/10/20-203762.webp"]'::jsonb, E'2024-10-23'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/11332', E'zh-Hans', 4, E'【仙台近郊】引人入勝的海鮮美食還有歷史悠久的神社！海都「鹽竈」的必去景點', E'靠近日本三景之一松岛的盐灶市，从仙台出发搭电车30分以内就能抵达。这个拥有悠久历史的海都渔业及水产加工业兴盛。本文将介绍推出超好吃海产美食的「海心」，以及港盐釜市鱼市场与盐灶神社等景点。\n\n盐灶市位在日本三景之一的松岛湾与东北第一大都市的仙台市之间，以渔业及制盐业闻名。\n\n盐灶的城镇发展于太平洋沿岸，已有1000年以上的历史。 平安时代时，「盐灶」这个地名已被当为歌枕（※1）在和歌中咏唱，而「盐灶」二字在和歌中会让人联想到的，是人们在月色下乘着小舟浮沉海面上，辛苦汲取海水制盐背后所流下的点滴泪水……。\n\n在平安时代资料中也曾出现的「盐灶神社」保留到现代，一路见证了这个城镇的悠远历史。本文将介绍盐灶神社以及盐灶市的必访景点，还有这里的海鲜美食。', E'["https://resources.matcha-jp.com/resize/720x2000/2022/09/07-129649.jpeg","https://resources.matcha-jp.com/resize/720x2000/2022/09/07-129645.jpeg","https://resources.matcha-jp.com/resize/720x2000/2022/09/07-129646.jpeg","https://resources.matcha-jp.com/resize/720x2000/2022/09/07-129647.jpeg"]'::jsonb, E'2022-10-19'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/9716', E'zh-Hans', 4, E'网罗仙台、松岛的主要景点！享受仙台城、松岛绝景、牛舌美食的1晚2日模范路线', E'本篇介绍东北地方的人气观光地、环游仙台和松岛的1晚2日模范路线。从历史建筑到美味的日式甜点等地域独有人气美食以及初次造访者必定想要一游的景点！请参考该模范路线，计划旅程吧。\n\n东北地方的交通要地是仙台。它是一处热门的观光地，既有战国武将伊达政宗的相关史迹，也有可口美食。另外，距离仙台市30分左右电车距离的松岛也是东北地方的必游观光地之一。\n\n本文面向初次造访的游客，介绍以仙台为据点、环游经典景点的1晚2日模范路线。第1日巡游仙台、第2日则移步到以景色优美著称的松岛！\n\n在仙台市内出行可选择JR、地铁、巴士等3种交通工具。1日游的话，建议选择仙台观光环城巴士“Loople仙台”的1日乘车券。成人630日元即可自由乘降，另外，出示乘车券即可享受仙台城资料馆、餐厅、伊达政宗灵庙瑞凤殿的门票折扣！', E'["https://resources.matcha-jp.com/resize/720x2000/2020/04/23-102002.webp","https://resources.matcha-jp.com/resize/720x2000/2020/04/23-101966.webp","https://resources.matcha-jp.com/resize/720x2000/2020/04/24-102031.webp","https://resources.matcha-jp.com/resize/720x2000/2020/04/24-102032.webp"]'::jsonb, E'2020-05-29'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/25099', E'zh-Hans', 5, E'[秋田]拥有超过100年历史！日本第一的花火大会——“大曲花火大会”', E'大曲花火大会是日本代表性的花火大会之一，每年在秋田县大仙市（旧大曲市）举行。该大会已有100多年的悠久历史，因其精湛的技艺和极高的声望而被誉为“日本第一花火大会”。\n\n大曲花火大会是日本最具代表性的花火大会之一，正式名称为“全国花火大会”。该大会于每年8月的最后一个星期六在秋田县大仙市（旧大曲市）的雄物川河畔举行，是吸引众多国内外游客的大型活动。\n\n该活动起源于1910年（明治43年），是一项传承了100多年、历史悠久且备受推崇的盛事。如今，它已成为日本最负盛名的烟花大会，来自全国各地的顶尖烟花师齐聚一堂，比拼技艺和艺术性。\n\n大曲烟花大会最大的特点是，它并非单纯的观赏性烟花，而是一场“比赛”。参赛的烟花公司屈指可数，而且所有燃放的烟花，无论在构图、色彩、时机、创意等方面，都拥有极高的完美度。', E'["https://resources.matcha-jp.com/resize/720x2000/2025/06/06-235675.webp","https://resources.matcha-jp.com/resize/720x2000/2025/06/06-235676.webp","https://resources.matcha-jp.com/resize/720x2000/2025/06/06-235678.webp","https://resources.matcha-jp.com/resize/720x2000/2025/06/06-235680.webp"]'::jsonb, E'2025-06-06'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/9532', E'zh-Hans', 5, E'[Ready For Japan!（朝日本进发！）第2辑]喜泪交并的感动！日本观光视频10选', E'在为下次旅行计划考虑时，大家免不了会想参考一下观光视频。日本多个地区制作了能饱览优美绝景、令人莞尔的视频。MATCHA编辑挑选了10则独特的观光视频，在此为大家介绍。\n\n近年来，日本各地方政府和企业制作了观光视频，发布在YouTube网站上。其中，有不少令人不禁莞尔又或感动的作品。\n\n按当前情势来看，大概有人不得不取消期待已久的访日旅行。不过，人们会为了下次的日本旅行而描画心中的梦想。还有，期待着什么时候就来日本玩玩。\n\n怀着这样的念头，小编们制作了连载“Ready For Japan!（朝日本进发！）第2辑”，收集了令人感动得喜泪交并的日本观光视频。', E'["https://resources.matcha-jp.com/resize/720x2000/2020/03/13-99413.webp","https://resources.matcha-jp.com/resize/720x2000/2020/03/13-99414.webp","https://resources.matcha-jp.com/resize/720x2000/2020/03/13-99415.webp","https://resources.matcha-jp.com/resize/720x2000/2020/03/13-99416.webp"]'::jsonb, E'2020-03-23'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/8090', E'zh-Hans', 5, E'【秋田】美人与文豪都爱！有秋田犬陪伴的秘境之宿—日景温泉', E'日本三大美人，其中一处就是秋田。秋田为何出美人？其中和当地温泉的泉质有关。来秋田一定要挑间温泉旅馆，享受舒服疗愈的美人汤。本篇介绍的日景温泉，便是当地为人所熟知的温泉旅馆，也有许多名人到访，还有秋田犬坐镇。秋季来，还能看到周边被红叶、银杏包围的秘境景致喔！\n\n“秋田美人”之所以闻名全国，是因为传说中日本古代最美的女人──小野小町便是出身自秋田县，白晢的皮肤衬上圆圆的大眼，甚至被称为“雪国里最艳丽的风景”。不过，为什么秋田盛产美人呢？这绝对跟温泉水质尤有关系。秋田的温泉水呈酸性为多，当地人也极爱泡温泉，皮肤自然光滑柔嫩。\n\n所以，去秋田绝对少不了挑间温泉旅馆，来泡上一个舒服疗愈的美人汤，比如本篇介绍的日景温泉，便是当地为人所熟知的名旅馆。\n\n朝阳下的日景温泉，衬上艳红的枫叶，就是一种日系慢活的调子。 位处于众多秋田名物发祥地的大馆市内的日景温泉，是一家知名度非常高的温泉旅馆，就连多位前任的日本首相也曾到访此处。这里在126年前所建，是经过历史洗礼的明治建筑物，可惜，曾因东北大地震而受影响，以致需闭馆翻新，虽然现在所看到的日景，是在去年10月才重新开幕的，但温泉的水质还是一如既往地蕴含丰富钙质，据说对皮肤病有治愈效果。', E'["https://resources.matcha-jp.com/resize/720x2000/2019/10/08-87731.webp","https://resources.matcha-jp.com/resize/720x2000/2019/10/08-87732.webp","https://resources.matcha-jp.com/resize/720x2000/2019/10/08-87733.webp","https://resources.matcha-jp.com/resize/720x2000/2019/10/08-87734.webp"]'::jsonb, E'2019-11-21'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/6458', E'zh-Hans', 6, E'山形・新潟的怀旧景点5选！来一趟穿越时空的旅行吧！', E'山形拥有以冬季雪景而闻名的银山温泉、以水路景观为特色的七日町、以上杉神社周边的历史景点而吸睛的米泽、以港湾美景而备受瞩目的酒田，新潟则有以传统市场与花街而出名的古町。这些充满浓浓怀旧氛围的人气景点，可以让你体验宛如穿越时空的快感喔！\n\n山形以产樱桃、葡萄、米泽牛而闻名，新潟则作为越光米和日本酒的产地也很有名气。这两个县除了给人美食之都的印象之外，其实还拥有许多令观光客为之疯狂的怀旧景点！\n\n以下要来向各位介绍山形、新潟县内古色古香的观光景点，以及如何节省交通费用的方式喔！\n\n除了拥有历史悠久的建筑物之外，也有许多由老旧建筑所改建的商业设施，也因此吸引了许多年轻人前来寻找新旧文化融合而生的新潮景点。', E'["https://resources.matcha-jp.com/resize/720x2000/2018/08/19-60942.webp","https://resources.matcha-jp.com/resize/720x2000/2018/08/19-60943.webp","https://resources.matcha-jp.com/resize/720x2000/2018/08/19-60944.webp","https://resources.matcha-jp.com/resize/720x2000/2018/08/19-60945.webp"]'::jsonb, E'2018-10-10'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/25347', E'zh-Hans', 6, E'山形米泽 2天1夜攻略：美食、自然与温泉的极致体验', E'本文将介绍在山形县米泽市1晚2日行程中必去的推荐景点，同时带您发现这座城市鲜为人知的魅力。\n\n山形县米泽市是一座四季风景优美的城下町，闻名遐迩。这里是与战国时代的武将上杉谦信、上杉鹰山有着深厚渊源的历史名镇，同时，这里还有着丰富的景点，例如米泽牛肉的美味佳肴、萤火虫飞舞的小野川温泉、可以尽情享受大自然的天元台高原等。从东京乘坐山形新干线约两小时即可到达山形山形县米泽市。这次，我们将介绍2天1夜旅行中值得游览的景点，以便您充分利用在米泽市的时间。希望通过这篇文章，大家能够了解到大家可能还不知道的米泽市山形县的魅力。在本文中，我们将重点介绍美食、美景和温泉。\n\n车站附近有租车、观光巴士和出租车，即使不会开车也能享受观光的乐趣。春秋两季租辆自行车去观光，感觉特别棒。\n\n在米泽市观光时，建议根据天气情况租借自行车。市内有三个地方可以租借自行车：米泽站、上杉伯爵邸（日本庭园）、米泽道之站。您还可以在米泽站和上杉伯爵府（日本花园）之间的任何地方归还车辆，因此您可以根据自己的旅行方式使用该服务。此外，这里还提供电动自行车租赁，出行十分方便。虽然数量有限，但部分自行车配有儿童座椅，带小孩出行的游客可以考虑租一辆。', E'["https://resources.matcha-jp.com/resize/720x2000/2025/07/07-238260.webp","https://resources.matcha-jp.com/resize/720x2000/2025/07/07-238282.webp","https://resources.matcha-jp.com/resize/720x2000/2025/07/07-238278.webp","https://resources.matcha-jp.com/resize/720x2000/2025/07/07-238279.webp"]'::jsonb, E'2025-07-08'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/21314', E'zh-Hans', 6, E'名湯宝库！「山形」必访温泉6选，周边景点、推荐旅馆介绍', E'山形县拥有众多名汤，如银山温泉等。即使是日归旅游，也能充分体验其魅力。本文将特别推荐6个温泉地，介绍各温泉的功效以及周边的观光景点。此外，详细介绍各温泉地的住宿设施，为您规划旅程提供参考信息。\n\n山形县拥有银山温泉、蔵王温泉、天童温泉、上山温泉等多个具有吸引力的温泉地，「うわの温泉 天神乃湯」等地点也非常适合日归游客前来享受。\n\n本文将向造访山形的朋友们介绍特别受欢迎的温泉地及其住宿设施。希望您能在本文中找到在山形的温泉中舒缓日常疲劳、心灵与身体重获放松的方法。\n\n山形县拥有众多温泉地，各具独特魅力。以下将特别挑选出5个值得一游的温泉地介绍给您。', E'["https://resources.matcha-jp.com/resize/720x2000/2024/08/29-194513.webp","https://resources.matcha-jp.com/resize/720x2000/2024/08/29-194515.webp","https://resources.matcha-jp.com/resize/720x2000/2024/08/29-194511.webp","https://resources.matcha-jp.com/resize/720x2000/2024/08/29-194514.webp"]'::jsonb, E'2024-09-10'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/11333', E'zh-Hans', 7, E'来磐城市享受太平洋魅力！大啖海鲜、体验绝景和水族馆之乐', E'福岛县的磐城市是日本太平洋沿岸让人心动的观光景点之一！以港町闻名，除了可以大快朵颐丰富海鲜，还能在以海洋生物为主题的水族馆留下难忘的回忆。这篇文章将介绍盘城市不可次过的特色、餐厅、和超级美味的鱼板专卖店。\n\n磐城市面朝东日本的太平洋沿岸地区，是暖流的黑潮和寒流的亲潮合流之处。这两道海流运来大量的浮游生物，吸引许许多多吃浮游生物的鱼类和海洋生物前来这片海域。因此，可在磐城市的外海捕获各式各样海产。\n\n例如日本最大的水族馆「福岛海洋科学馆」，可以看到海中生物、认识世界上的海洋生物。如果是想欣赏海街独有的美景，也可登上「磐城海洋塔」。\n\n要是想在附近住一晚，推荐磐城汤本温泉。可在这里的「夏威夷度假村 (Spa Resort Hawaiians)」体验太平洋沿岸部发展出多采多姿的文化。', E'["https://resources.matcha-jp.com/resize/720x2000/2022/09/22-129968.webp","https://resources.matcha-jp.com/resize/720x2000/2022/09/22-129997.webp","https://resources.matcha-jp.com/resize/720x2000/2022/09/22-129972.webp","https://resources.matcha-jp.com/resize/720x2000/2022/09/22-129983.webp"]'::jsonb, E'2022-10-19'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/10594', E'zh-Hans', 7, E'一日一食，真味本源！法式料理人与福岛生产者的强强联合，体会当地食材的真正魅力！', E'法式料理Hagi究竟有什么样的魅力让国内外的饕客愿意专程来福岛就为品尝萩主厨一流的手艺呢？历经2011年大震灾后，萩主厨意识到必须更了解第一线生产者的心声并且同心协力推广，才能让在地食材在餐桌上发挥的淋漓尽致。时隔十年的现在，始终没变的是他对料理的热忱与对家乡的关爱，让我们一起来感受法式料理Hagi的独特风采吧！\n\n在问及萩主厨当初想踏入料理界的契机时，他面露微笑，温柔地回答到：“我的外婆拥有自己的菜园，因此餐桌上的蔬菜大多都是她精心培育的成果。那时候便觉得取于大自然的食材原来可以这么美味，因而产生了想成为料理人的想法。”。主厨曾于求学时期就读辻调理专门学校的法国校区料理学科，那时未知又充满魅力的法式料理所带给自己的震撼极大，因此即便学成归国，也希望将汁多味腴，讲究五官飨宴的法式料理特色，以在地食材及日本独有的食文化融合，提供给每一位客人。\n\nHagi法式料理餐厅拍摄 在311大震灾后的两年之间，由于浓渔牧产业受到重创，检验超标的食材都无法流入市场，而失去家园的居民也纷纷离开居住地，与“饮食”相关的单位与店家包括Hagi也都几乎无法维持经营。在看到浓渔牧产业等生产者们即便遇到困难也得继续留在原地工作的艰辛模样后，他决定伸出援手自愿以义工身份到福岛各地参与栽种等工作，并且在过程中渐渐了解到“地产地销”的重要性与其食材无可取代的鲜度。\n\nHagi法式料理餐厅拍摄 在食材有限的情况下，要如何让大家仍能在品尝料理时露出满意笑容呢？于是他决定以“一日一组”的方式再次敞开店门迎接客人。 2021年的现在，整体复兴状况逐渐恢复，有足够的福岛产蔬菜、鱼、肉能供应给餐饮业，因此可以接待更多特地前来的客人，目前已经改为同一时段最多接受十人预约。', E'["https://resources.matcha-jp.com/resize/720x2000/2022/01/07-119884.webp","https://resources.matcha-jp.com/resize/720x2000/2022/01/07-119885.webp","https://resources.matcha-jp.com/resize/720x2000/2022/01/07-119886.webp","https://resources.matcha-jp.com/resize/720x2000/2022/01/07-119887.webp"]'::jsonb, E'2021-12-22'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/9376', E'zh-Hans', 7, E'【福岛】2天1夜的绝景＆美食之旅该怎么玩？租车自驾或搭电车的旅游攻略', E'美酒，佳肴，绝景已经足够让人心动，还有温泉乡的治愈，历史小镇的熏陶，距离东京只需2小时车程的福岛绝对是日本旅行的代表地点之一。这里浓缩了日本旅行的全部精华。让小编为大家详细规划，不管是乘车前往，还是租车自驾，有了小编的懒人包保准玩的痛快。\n\n古城内充满历史情怀的古街，一望无际的雪原之景，温泉，美酒样样不缺。这就是东京只需两小时车程即可抵达的日本福岛县的无穷魅力。\n\n今天小编特别为不知如何是好的朋友准备了，如何利用铁路・巴士等公共交通，以及租车自驾来完美度过2天1夜的行程。不管怎样出行，沿途都是风光无限哦！\n\n选择乘坐新干线、JR、高速巴士等公共交通前往福岛时，建议选择会津若松或是磐城作为落脚点。', E'["https://resources.matcha-jp.com/resize/720x2000/2020/01/22-95529.webp","https://resources.matcha-jp.com/resize/720x2000/2020/01/30-96029.webp","https://resources.matcha-jp.com/resize/720x2000/2019/05/21-77424.webp","https://resources.matcha-jp.com/resize/720x2000/2020/01/22-95521.webp"]'::jsonb, E'2020-03-18'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/8138', E'zh-Hans', 8, E'【茨城】谁说茨城没魅力？让满桌的茨城美食来扳回一城！', E'近期以花海绝景知名的东京近郊【茨城】，除了自然美景，其实还有多样在地美食！除了最有名的纳豆之外，还有当地限定的美味和牛、产量第一的哈密瓜与栗子、满满胶原蛋白的鮟鱇鱼、日本酒等。自认是吃货的你，到茨城旅行怎能错过这些地方美食呢？\n\n距离东京不远的茨城县拥有多处风景名胜，提供东京人们放假踏青的好去处。受惠于温暖气候和肥沃土地，茨城县以丰富的农产品、海鲜、肉品等，支撑着东京家家户户的餐桌，今天小编就来介绍几样知名的食材、料理，带大家认识茨城这座食物宝库。\n\n说到茨城，就会想到纳豆。纳豆在茨城县的历史已有千年之久，据说在1083年源义家远征东北路过“常陆国(现茨城一带)”时，将剩下的煮熟豆子用藁(稻梗或麦梗) 包裹起来，豆子自然发酵后牵丝变得很美味，是纳豆最早的样子。纳豆也因这趟远征之旅，在关东地区较为盛行。\n\n茨城县内主要河川“那珂川”，过去因治水技术不发达而经常泛滥。当时的水户藩鼓励大家在台风来袭前先采收大豆，但早采收的大豆颗粒较小，不适合加工成豆腐或味噌，却正好适合制作纳豆。明治时代常磐线开通后，纳豆成为水户的伴手礼，在全日本打开知名度。在水户车站前也有这座纳豆雕像，足见纳豆的重要性。', E'["https://resources.matcha-jp.com/resize/720x2000/2019/10/22-88771.webp","https://resources.matcha-jp.com/resize/720x2000/2019/10/22-88780.webp","https://resources.matcha-jp.com/resize/720x2000/2019/10/22-88773.webp","https://resources.matcha-jp.com/resize/720x2000/2019/10/22-88774.webp"]'::jsonb, E'2019-11-21'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/25326', E'zh-Hans', 8, E'【关东地区】秋季赏樱，一起来赏樱吧！4个热门景点推荐🍁', E'秋天是自然之美格外引人注目的季节。气温温和，空气清新舒适，正是郊游散步的好时节。山峦上，红叶点缀其间，独特的秋景令人心旷神怡。\n\n秋季，一个拥有丰富多彩享受方式的季节。气温渐​​暖，空气更清新，正是郊游散步的好时节。群山变幻色彩，自然之美被认为是一年中最令人心驰神往的季节。\n\n秋天里一定不能错过的一种植物是“藜芦”，这是一种一年生植物，在日语中被称为“hokigusa”。\n\n藜芦属一年生植物，属于苋科藜芦属，日语名为“こちゃん”。其名称源于古代将成熟的茎干燥后用作扫帚。藜芦的特点是其独特的圆形和蓬松的形状，看起来非常可爱。', E'["https://resources.matcha-jp.com/resize/720x2000/2025/07/03-238066.webp","https://resources.matcha-jp.com/resize/720x2000/2025/07/03-238089.webp","https://resources.matcha-jp.com/resize/720x2000/2025/07/03-238068.webp","https://resources.matcha-jp.com/resize/720x2000/2025/07/03-238069.webp"]'::jsonb, E'2025-07-03'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/12698', E'zh-Hans', 8, E'【东京近郊】来日本第二大湖“霞浦”，骑单车品美食日本第二大湖霞浦湖的推荐活动和美食', E'霞浦湖位于茨城县，距离东京约一小时车程，是日本第二大湖。 自古以来，这里捕获的各种鱼类被加工成佃煮。 本文将为您介绍佃谷的魅力以及霞浦湖周边的活动和观光景点。\n\n位在茨城县东南部的【霞浦】 ，是日本面积第2大的湖泊，湖岸一周长达252千米。从东京只要约1小时即可抵达，是关东地区的人气观光地。\n\n霞浦周边有许多可以徜徉在超美景色中的户外活动，像是可以搭船参观航行在湖面的“帆引船”，或是在湖边骑单车铁马游等，各种这里才有的体验活动，琳琅满目十分精采。\n\n而且霞浦为淡水湖，盛产公鱼及白鱼、淡水虾等种类多元的鱼类，当地也很多水产加工业者，可以找到这里才有的好吃美食喔。', E'["https://resources.matcha-jp.com/resize/720x2000/2023/08/30-144617.webp","https://resources.matcha-jp.com/resize/720x2000/2023/08/30-144613.webp","https://resources.matcha-jp.com/resize/720x2000/2023/08/30-144606.webp","https://resources.matcha-jp.com/resize/720x2000/2023/08/30-144614.webp"]'::jsonb, E'2023-10-17'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/21527', E'zh-Hans', 9, E'【栃木】享受日光枫叶：绝美赏枫景点12选', E'在日光，壮观的秋色与世界遗产的建筑相融合，成为东京附近最佳的秋季旅游目的地之一。我们介绍12个拥有壮丽红叶的地点，从中禅寺湖和华严瀑布到日光东照宫。\n\n日光 一直是许多日本历史名人的历史避难所。从东京搭乘火车仅需两小时，日光是短途旅行的理想地点，特别是在秋季，充满壮丽的自然美景！\n\n由于海拔较高，中禅寺湖和华严瀑布一带的红叶最早可在十月中旬至十月底时出现。日光的世界遗产地区则可以在十一月初至中旬欣赏到美丽的红叶。\n\n华严瀑布四季皆美，尤其在秋天，周围的森林化身为红、橙、金色的灿烂景象，真的如梦似幻。', E'["https://resources.matcha-jp.com/resize/720x2000/2024/09/11-196845.webp","https://resources.matcha-jp.com/resize/720x2000/2024/09/09-196365.webp","https://resources.matcha-jp.com/resize/720x2000/2024/09/16-197665.webp","https://resources.matcha-jp.com/resize/720x2000/2024/09/14-197482.webp"]'::jsonb, E'2024-09-17'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/11518', E'zh-Hans', 9, E'还只知道足利花卉公园吗？！栃木县超赞的6个赏花好去处推荐！', E'很多人都知道栃木县自然景观十分丰富，拥有日本首屈一指的花卉主题公园【足利花卉公园】，但其实这里还有很多其他非常值得一看的花卉美景哦！今天小编就为您详细介绍6处超级推荐的【栃木县绝佳赏花地】，希望能为您的栃木行程添上缤纷多彩的一笔！\n\n枥木县位于东京以北，以其美丽的自然风光和壮观的景色而闻名，拥有一座日本领先的花卉主题公园【足利花卉公园】。 从高山到平原，丰富的地形孕育了包括高原山间花卉在内多种多样的花卉品种，仅栃木县内就有多个绝佳的赏花目的地。\n\n本文为您介绍栃木县的6个规模最大、最上镜、最壮观的赏花景点。从人尽皆知的网红景点到不为人知的小众秘境，相信您一定能在其中找到您想打卡的那片花海！\n\n其中，最受欢迎的，当属4月中旬至5月中旬盛开的紫藤花，美轮美奂。 紫藤花架上垂下的花朵犹如流淌的瀑布，绵延80米长的“紫藤隧道”更是绝无仅有的壮美景观。 在每年这个时候举行的 "紫藤花物语 "活动中，紫藤花被灯光点亮后显得更为梦幻。', E'["https://resources.matcha-jp.com/resize/720x2000/2022/12/16-132916.webp","https://resources.matcha-jp.com/resize/720x2000/2022/12/16-132914.webp","https://resources.matcha-jp.com/resize/720x2000/2022/12/16-132917.webp","https://resources.matcha-jp.com/resize/720x2000/2023/01/16-133783.webp"]'::jsonb, E'2023-01-23'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/1700', E'zh-Hans', 9, E'穿越到江户时代，来「日光江户村」寻找武士和忍者吧！', E'对现代的日本人来说，走在街上不会看见武士或忍者是理所当然的事。但还是有不少的外国人心中有着“日本＝武士、忍者”的印象。\n\n那就是以江户时代为概念打造而成的主题乐园“日光江户村”，在这里能够亲眼看见忍者和武士。\n\n在日光江户村中，分为街道(通往江户的道路)、宿场町(为了旅人而设满旅馆的城镇)、商家街(市场区)、武家屋敷(武士住宅)、忍者之里(忍者村)共五个区域。每个区域都独具特色，在这里能够享受独特的城镇风貌。在村内一路上能看见武士们来来往往，感受到彷佛误入江户时代般的新奇体验。\n\n在进入日光江户村之前，首先要先通过这里的关所(类似检查哨)，在一旁的售票处购买“通关证(通行手形)”通关后，就马上来穿越到江户时代吧！', E'["https://resources.matcha-jp.com/old_thumbnails/720x2000/1700.webp"]'::jsonb, E'2016-03-26'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/7337', E'zh-Hans', 10, E'草津温泉', E'草津温泉（日语：草津温泉／くさつおんせん，罗马化：Kusatsu onsen），位于日本群马县吾妻郡草津町的温泉名胜地。\n\n其起源已有千年之久。1，是强酸性硫黄泉，具有医疗功效。是林罗山的日本三名泉之一。江户时代的温泉番付中名列当时最高位的东大关，是日本的代表名泉之一。\n\n位于中心区域的“汤畑”，是草津温泉最主要的景点。利用富含木脂的松木或桧木架设的温泉田，引流源源不绝的汤泉。其泉水的温度高达摄氏65度，无法直接进去泡，因此木架隔出的汤畑除了引流温泉之外，更有助于散热，降至适合浸泡的温度。\n\n除了汤畑之外，“时间汤”是草津温泉从古流传至今的泡汤治疗法，透过“吟唱”与“汤揉”让泡汤更加神圣同时缩短等待降温的时间。', E'["https://resources.matcha-jp.com/resize/720x2000/2019/05/07-76354.webp","https://resources.matcha-jp.com/resize/720x2000/2019/04/24-75960.webp","https://resources.matcha-jp.com/resize/720x2000/2019/04/24-75961.webp","https://resources.matcha-jp.com/resize/720x2000/2019/05/09-76485.webp"]'::jsonb, E'2019-06-17'::timestamptz, E'草津温泉', E'Wikipedia (CC BY-SA 4.0)', E'https://zh.wikipedia.org/wiki/%E8%8D%89%E6%B4%A5%E6%B8%A9%E6%B3%89'),
(E'https://matcha-jp.com/cn/25804', E'zh-Hans', 10, E'[群马] 群马秋季美景之旅：报德寺、吹割瀑布、老神温泉', E'群马县拥有丰富的自然、历史和文化。秋季，寺庙、神社、溪谷、瀑布、温泉等地的红叶缤纷多彩。本文将介绍著名的红叶景点及其历史，以及当地特色美食。\n\n群马县自古以来作为连接关东地区和北陆地区的交通要道而繁荣昌盛，是山岳信仰和温泉文化根深蒂固的地区。以上毛三山（赤城山、榛名山、妙义山）为代表的山脉自古以来就备受人们的信仰，至今仍守护着丰富的自然环境。\n\n秋季来临，群马大地一片绚丽多彩。历史悠久的寺庙神社、温泉、雄伟的溪谷和瀑布，都被鲜艳的红叶笼罩，令人心驰神往。历史的韵味与自然的色彩交相辉映，正是群马独有的秋季魅力。\n\n在本文中，我们将介绍群马著名的红叶景点、其传承的历史以及丰富您的旅行体验的当地美食。', E'["https://resources.matcha-jp.com/resize/720x2000/2025/09/12-244107.webp","https://resources.matcha-jp.com/resize/720x2000/2025/09/12-244109.webp","https://resources.matcha-jp.com/resize/720x2000/2025/09/12-244110.webp","https://resources.matcha-jp.com/resize/720x2000/2025/09/12-244111.webp"]'::jsonb, E'2025-09-12'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/9330', E'zh-Hans', 10, E'历史的留存，时光的印证—来富冈感受日本的传承', E'坐拥世界遗产“富冈制丝场”的群马县富冈市内，古建筑，怀旧街景随处可见，历史氛围浓厚，魅力完全不输世界遗产。制丝场周边还有不少经过改建的古民家咖啡店等，悠闲的散步其中，感受日本百年的传承。\n\n说到群马县，不少人脑中都会浮现出，被认定为世界遗产的“富冈制丝场”。但其实，富冈的魅力不仅仅在于此，周边的怀旧街景，老店名品都非常值得一探。\n\n单看制丝场略感不够的朋友一定不在少数！古民家改建的复古咖啡厅，老店林立的商业街等，最让人憧憬的还是生活在世界遗产周边，依然保持古时传承的一般百姓生活。从富冈也可轻松前往度假胜地轻井泽，规划行程时，不妨一起考虑哦。跟着小编一起，来探寻不一样的富冈吧！\n\n来到富冈，第一站当然是，于2014年认定为世界遗产的富冈制丝场了。宽广的遗产境内，创立于1872年，支撑起日本近代制丝业的建物群依然挺立在那里。', E'["https://resources.matcha-jp.com/resize/720x2000/2020/01/29-95945.webp","https://resources.matcha-jp.com/resize/720x2000/2020/01/29-95946.webp","https://resources.matcha-jp.com/resize/720x2000/2020/01/28-95864.webp","https://resources.matcha-jp.com/resize/720x2000/2020/01/28-95871.webp"]'::jsonb, E'2020-02-19'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/5741', E'zh-Hans', 11, E'东京近郊最强能量景点之一！走访三峰神社&冰之绝景', E'从东京出发3小时车程的埼玉县秩父市的三峰神社，是东京近郊最强能量景点之一，据说在工作运和恋爱运方面很灵验。就近还能欣赏到三十槌之冰柱，看结冰的岩清水成为冰之艺术。本文便为大家介绍走访能量景点和绝景的一日游推荐行程。\n\n很多参拜者都有过这样的经历，因此埼玉县秩父市的三峰神社，成为了包括东京近郊6县在内的关东地方，最大的能量景点之一，广为人知。\n\n不仅在工作和财运、爱情方面能带来好运，冬季在神社附近，还能欣赏到巨大的天然冰柱三十槌之冰柱，吸引了很多游客的造访。\n\n本文将围绕东京到三峰神社和“三十槌之冰柱”，为大家介绍相关信息和一日游行程推荐。', E'["https://resources.matcha-jp.com/resize/720x2000/2018/02/08-47614.webp","https://resources.matcha-jp.com/resize/720x2000/2018/02/08-47610.webp","https://resources.matcha-jp.com/resize/720x2000/2018/02/08-47611.webp","https://resources.matcha-jp.com/resize/720x2000/2018/02/08-47612.webp"]'::jsonb, E'2018-03-07'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/5405', E'zh-Hans', 11, E'东京出发当天来回的赏枫景点〜在埼玉县长瀞町尽享美食与绝景', E'说到日本赏红叶的景点，想必大家都会想到京都、箱根和日光等著名的景点。但在东京附近的埼玉县，也有毫不逊色的赏枫景点哦。本篇文章介绍了从新宿只需2个小时就能到达的人气景点——长瀞町的1日周游路线。\n\n其中最为知名的是长瀞町湍流的荒川沿岸边，长500米，宽80米，被称为“岩畳”的巨大天然岩石。\n\n进入11月，群山渐红，日本各地的游客都会前来长瀞町，就为一睹雄伟的岩畳河岸与艳丽的红叶相辅相成的美景。\n\n从新宿搭乘列车只需2小时，因此这里无论是当日往返还是暂留过夜都很方便，地理位置绝佳。', E'["https://resources.matcha-jp.com/resize/720x2000/2017/11/24-42148.webp","https://resources.matcha-jp.com/resize/720x2000/2017/11/24-42149.webp","https://resources.matcha-jp.com/resize/720x2000/2017/11/24-42150.webp","https://resources.matcha-jp.com/resize/720x2000/2017/12/15-43888.webp"]'::jsonb, E'2017-12-21'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/11526', E'zh-Hans', 11, E'【埼玉】购物商城＋OUTLET！免税好物，居家美食，日本超级购物中心【AEON Lake Town】欢迎您', E'埼玉县越谷市的【AEON Lake Town】是日本最大规模的购物设施之一，但是免税店与OUTLET店铺数就多达700间！东京主要车站出发，车程不过1小时，十分便利。来东京购物的话，不想赶场把时间花在路上。不如安排一天来Lake Town，保证买到让你心花怒放！\n\nAEON Lake Town乘坐电车就可轻松抵达。距离东京也不过1小时的车程。在越谷Lake Town站下车即到。 即使在全国的永旺梦乐城中，这里的规模也是王者级别的，除了全区分成kaze、mori跟OUTLET外，还有超过700家店铺，多到让人看到目不暇给，一定可以满足所有人的购物需求！\n\n和所有永旺梦乐城一样，【AEON Lake Town】也提供超值的免税服务，逛街更是轻松无负担。有什么绝不能错过的免税店？小编为你一一介绍。\n\n您喜欢怎样的假日生活呢？是喜欢在家静静享受悠闲的午茶时光，还是背起背包出外踏青？不论怎样的模式吸引你，在这里都可以找到心仪的物品。', E'["https://resources.matcha-jp.com/resize/720x2000/2022/12/19-132981.webp","https://resources.matcha-jp.com/resize/720x2000/2023/04/19-137288.webp","https://resources.matcha-jp.com/resize/720x2000/2022/12/20-132997.webp","https://resources.matcha-jp.com/resize/720x2000/2022/12/20-132998.webp"]'::jsonb, E'2023-02-16'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/20846', E'zh-Hans', 12, E'海岸风光与广阔视野！「千叶」严选温泉19选！介绍旅馆、饭店，还有可以一日游的热门景点。', E'千叶县是适合一日游或住宿旅行的理想地区。这里将介绍在千叶值得推荐的温泉地点，以及受欢迎的温泉旅馆和饭店。同时也会介绍可以享受日归温泉的 Spa。本文包含地图，您可以寻找出适合您前往的地点。\n\n千葉县位于都心附近，环绕着美丽的海洋和山脉，有许多风景优美的地方，也有很多温泉。\n\n白滨町位于房总半岛的南端，南房总市，风景优美，可以一览太平洋的绝景。这里有许多观光胜地，如可观赏夕阳的「野岛崎灯塔」，您可以享受许多景点，并参加冲浪、潜水等海洋运动。\n\n「白滨海洋度假村」的所有房间都能观赏到海景。您可以在享受海景的同时泡温泉。温泉的成分是氯化钠-碳酸氢盐泉，可以从体内温暖，促进血液循环。', E'["https://resources.matcha-jp.com/resize/720x2000/2024/08/09-191873.webp","https://resources.matcha-jp.com/resize/720x2000/2024/08/09-191874.webp","https://resources.matcha-jp.com/resize/720x2000/2024/08/09-191877.webp","https://resources.matcha-jp.com/resize/720x2000/2024/08/09-191871.webp"]'::jsonb, E'2024-08-15'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/5988', E'zh-Hans', 12, E'不容错过！东京迪士尼乐园35周年特别庆典“Happiest Celebration!”', E'东京迪士尼度假区以35周年庆，在2018年4月15日(周日)到2019年3月25日(周一)，将举办纪念庆典“东京迪士尼度假区35周年“Happiest Celebration””。此文将向您介绍，在东京迪士尼乐园举行的活动看点。\n\n东京迪士尼乐园，为纪念开园35周年，在2018年4月15日(周日)到2019年3月25日(周一)期间，将举行周年庆「东京迪士尼渡假区35周年“Happiest Celebration”」。\n\n日间游行“奇想腾飞！”为东京迪士尼度假区35周年庆开启序幕。米奇和布鲁托一起乘坐豪华的花车闪亮登场。\n\n高飞作为梦幻世界的引路人首先登场。后续还有大家熟知的迪士尼明星们，他们载歌载舞把游行推向高潮。', E'["https://resources.matcha-jp.com/resize/720x2000/2018/04/12-52180.webp","https://resources.matcha-jp.com/resize/720x2000/2018/04/12-52181.webp","https://resources.matcha-jp.com/resize/720x2000/2018/04/12-52182.webp","https://resources.matcha-jp.com/resize/720x2000/2018/04/12-52183.webp"]'::jsonb, E'2019-02-28'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/4644', E'zh-Hans', 12, E'东京迪士尼度假区内交通指南看这里！ 了解迪士尼度假区线', E'游玩东京迪士尼乐园，东京迪士尼海洋等东京迪士尼度假区的最佳选择就是乘坐“迪士尼度假区线”。MATCHA小编带您看看这里的独特魅力和交通方式。\n\n东京迪士尼度假区，这片梦幻王国不仅面积大，还建有很多酒店和休闲设施。到不同的地方，仅靠走路是非常困难的。小编给您介绍游玩东京迪士尼度假区时，“迪士尼度假区线”的乘坐方式以及只有在这里才能体会到的乐趣。\n\n车站共有4个。东京迪士尼乐园最近的“东京迪士尼乐园站”，伊克斯皮儿莉以及迪士尼大使大饭店附近的“度假区总站”，还有东京迪士尼海洋以及东京迪士尼海洋观海景大饭店最近的“东京迪士尼海洋站”，以及迪士尼度假区公认饭店附近的“海滨站”下车都很方便。\n\n迪士尼度假区线是在空中运行的，环绕东京迪士尼度假区一周的单轨电车，要上楼梯到2楼上车，可以带您前往度假区内各大设施。', E'["https://resources.matcha-jp.com/resize/720x2000/2017/06/26-29535.webp","https://resources.matcha-jp.com/resize/720x2000/2017/06/26-29537.webp","https://resources.matcha-jp.com/resize/720x2000/2017/06/26-29539.webp","https://resources.matcha-jp.com/resize/720x2000/2017/06/26-29541.webp"]'::jsonb, E'2018-04-30'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/27030', E'zh-Hans', 13, E'3小时体验御宅文化！秋叶原动漫游戏探险之旅完整指南', E'本文介绍了一条颇受欢迎的导览路线，让您在大约三个小时内充分体验秋叶原的动漫和游戏文化。该路线高效地带您前往女仆咖啡厅、复古游戏厅、扭蛋机体验馆等等，即使是初次体验者也能享受到安全愉快的旅程。\n\n目次 什么是秋叶原动漫游戏冒险之旅？ 旅游行程详情 推荐给这类人 想了解东京旅行信息，请咨询 TripToJapan！ 什么是秋叶原动漫游戏冒险之旅？ 探索秋叶原充满活力的街道。作为东京著名的动漫和游戏街区，这里汇集了游戏厅、特色商店，以及正宗的女仆咖啡厅体验。发掘隐藏的宝藏，沉浸在独特的日本流行文化世界中。\n\n旅游行程详情 ①走进复古游戏店，进入一个充满怀旧气息的世界。 您可以体验日本游戏文化的历史，还可以玩到像 Famicom 这样的经典游戏。\n\n这里提供种类繁多的手办、cosplay道具和周边商品。此外，还有指南介绍角色的背景故事。', E'["https://resources.matcha-jp.com/resize/720x2000/2026/04/16-262788.webp","https://resources.matcha-jp.com/resize/720x2000/2026/04/16-262790.webp","https://resources.matcha-jp.com/resize/720x2000/2026/04/16-262797.webp","https://resources.matcha-jp.com/resize/720x2000/2026/04/16-262789.webp"]'::jsonb, E'2026-04-16'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/10497', E'zh-Hans', 13, E'【2026】赏樱之后准备赏紫藤花！东京人气紫藤景点10选！', E'迎风摇摆的紫藤花惹人怜爱，是日本春天不可或缺的绝景。想知道东京都内哪里可以欣赏这柔美的紫藤帷幕吗？除了最有人气的龟户神社之外，还有哪些可以避开人潮静下来欣赏呢？快看小编挑选的东京10处赏藤名所！\n\n樱花凋谢后，杜鹃、花水木、牡丹等接连盛开，一片百花缭乱中，垂吊的紫藤花别具风情。日本人在很久很久以前就对紫藤着迷不已，日本最古的和歌集《万叶集》中，歌诵紫藤的诗歌多达27首。平安时代贵族们的衣着也採用藤花的图样，藤原氏的家纹也源自藤花。\n\n紫藤早已融入日本人生活，因此即便是高楼林立的东京都内也有好几个名所可欣赏。接下来小编挑选东京都内10处欣赏紫藤的地点，轻松就可排入行程！\n\n龟户天神社大概是东京最知名的紫藤名所吧！其历史可溯及江户时期，在着名的《名所江戸百景》中描绘了龟户天神的紫藤景色。每年四月中下旬，社内15棚100株以上的紫藤花一齐绽放，相当壮观。一串串小巧可爱、随风摇曳的紫藤花映着朱红色的太鼓桥，突显紫藤的娇嫩。自江户以来的紫藤花配上平成象徵的晴空塔，进行一场时空交错的对谈。', E'["https://resources.matcha-jp.com/resize/720x2000/2021/04/23-113831.webp","https://resources.matcha-jp.com/resize/720x2000/2021/04/23-113832.webp","https://resources.matcha-jp.com/resize/720x2000/2021/04/23-113845.webp","https://resources.matcha-jp.com/resize/720x2000/2021/04/23-113833.webp"]'::jsonb, E'2026-04-14'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/24847', E'zh-Hans', 13, E'【新手入门】ICOCA、Suica、PiTaPa 的比较——包含智能手机版的完整指南', E'本文是针对访日外国游客以及以关西地区为中心旅游的游客提供的指南，对主要交通IC卡“ICOCA”、“PiTaPa”、“Suica”进行了清晰的比较，并解释了它们之间的区别。\n\nICOCA是JR西日本发行的IC卡，是前往关西地区（大阪、京都、神户等）旅行最推荐的卡。您还可以使用它在火车、公共汽车、便利店等处购物。\n\n如果您计划前往关西地区旅行，请咨询日本旅游专家 Trip To Japan！Trip To Japan 提供各种各样的活动，从美食之旅到文化体验之旅，应有尽有。\n\n拥有ICOCA这样的IC卡，在日本旅行会非常方便！办一张ICOCA卡，就能参加大阪的美食之旅，或者京都的私人旅行！', E'["https://resources.matcha-jp.com/resize/720x2000/2025/06/13-236527.webp","https://resources.matcha-jp.com/resize/720x2000/2025/06/13-236528.webp","https://resources.matcha-jp.com/resize/720x2000/2025/06/13-236529.webp","https://resources.matcha-jp.com/resize/720x2000/2025/06/13-236530.webp"]'::jsonb, E'2025-05-05'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/3895', E'zh-Hans', 14, E'每一站都想下车打卡！江之电真正该拍的景点', E'买一张六百日币江之电一日券，想来个鎌仓一日游却总是走马看花，除了去灌篮高手平交道漫画朝圣地跟大佛拍照之外就不知道要去哪里了吗？这次小编要亲自推荐给大家真的该值得一去的小站与景点！龙恋之钟,江之岛Island SPA,bills,极乐寺,成就院,御灵神社,鎌仓文学馆,鸠SABURE,Walk大町等等千万别错过啰！\n\n买一张八百日币江之电一日券，却总是走马看花，除了去灌篮高手漫画朝圣地跟大佛拍照之外就不知道要去哪里了吗？这次小编要亲自推荐给大家真的该值得一去的小站与景点！\n\n若往爬上江之岛顶端的反方向走几步路后，就能来视野极佳且被称为恋人之丘的丘地。据传这里是龙和弁天结缘之地，因此情侣一起敲响「龙恋之钟」就能得到爱的成就。围栏上挂有许多情侣们挂上的南京锁，据说这能使两个人的爱更稳固喔。\n\n江之岛上有个可以眺望海景，边泡温泉的设施。里头最为推荐的就是一望无际的临海户外泳池区。还有可以把脚伸直泡的平台，想泡多久就待多久！完全可以感受到大海就在眼前的辽阔感。', E'["https://resources.matcha-jp.com/resize/720x2000/2017/01/20-14271.webp","https://resources.matcha-jp.com/resize/720x2000/2017/01/20-14272.webp","https://resources.matcha-jp.com/resize/720x2000/2017/01/20-14273.webp","https://resources.matcha-jp.com/resize/720x2000/2018/07/03-57540.webp"]'::jsonb, E'2017-11-08'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/25049', E'zh-Hans', 14, E'【湘南】THE OUTLETS SHONAN HIRATSUKA 完全指南！购物、折扣家电与本地美食一次尽享！', E'【THE OUTLETS SHONAN HIRATSUKA】是一座能让您尽情感受湘南地区在地魅力的奥特莱斯商城。除了有大型家电量贩店进驻，还有能眺望富士山美景的公园区域，并汇聚了丰富的本地美食。本篇文章将为您详细介绍这座综合型购物设施的魅力亮点。\n\n如果打算来东京近郊旅游，想必大家都希望能在旅途中一次体验购物与在地魅力。能满足这种期待的，正是由永旺集团全新打造的复合型商业设施 —— THE OUTLETS SHONAN HIRATSUKA（THE OUTLETS 湘南平冢）。\n\n在THE OUTLETS 湘南平冢，不仅集结了丰富多样的品牌，还有能眺望富士山的绝美景致、当地特色美食，以及让孩子尽情奔跑玩耍的宽阔草坪广场。\n\nTHE OUTLETS SHONAN HIRATSUKA 所在地为节奏悠闲、生活气息浓厚的神奈川县湘南平冢地区。这里也是东京居民周末前往郊区放松休闲的人气目的地之一。', E'["https://resources.matcha-jp.com/resize/720x2000/2025/06/02-235061.webp","https://resources.matcha-jp.com/resize/720x2000/2025/06/02-235062.webp","https://resources.matcha-jp.com/resize/720x2000/2025/06/02-235063.webp","https://resources.matcha-jp.com/resize/720x2000/2025/06/02-235064.webp"]'::jsonb, E'2025-06-24'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/20736', E'zh-Hans', 14, E'横滨约会景点11选！包含适合雨天的行程与省钱选择', E'一提到横滨，就会让人联想到成熟大人情侣喜爱的旅游胜地，娱乐设施众多。本文中我们将介绍雨天也能约会的地点以及省钱选择等，适合各种情境的横滨约会景点。\n\n时尚成熟的大人约会，想到的就是横滨。这里拥有众多热门的娱乐设施，交通方便，让你轻松出游。但是，当真的来到约会时，有时不知道该去哪里。\n\n因此，在本文中，我们将介绍各种情境下，大人情侣可以尽情享受横滨约会的地点，无论是下雨天适合的地方，还是适合省钱的约会地点。\n\n横滨是个受欢迎的约会区域，拥有着各种能够享受的地点，现在先来介绍经典的约会地点。这些地点无论规模大小，都能让人一次又一次地享受其中。不论是第一次来的人还是经常来的人，请务必查看。', E'["https://resources.matcha-jp.com/resize/720x2000/2024/07/26-189778.webp","https://resources.matcha-jp.com/resize/720x2000/2024/07/28-190089.webp","https://resources.matcha-jp.com/resize/720x2000/2024/07/28-190090.webp","https://resources.matcha-jp.com/resize/720x2000/2024/07/28-190091.webp"]'::jsonb, E'2024-08-01'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/25331', E'zh-Hans', 15, E'【关东红叶】秋季旅行季来袭！关东地区秋季必游景点', E'随着秋季的到来，关东地区的山峦和公园里都披上了美丽的红叶。10月份是观赏红叶和黄叶的最佳时节，许多人慕名而来，欣赏这片生机勃勃的自然风光。\n\n在日本，秋天的山峦和行道树都会染上红叶，自古以来就有“赏枫”的习俗。除了春天赏樱之外，赏枫也是感受四季变迁的重要文化。尤其是在10月到11月，枫树和银杏树染上美丽的色彩，许多人都会前往著名的红叶胜地，沉浸在大自然的美景中。这里也是热门的旅行和一日游目的地，寺庙、神社、公园和山区经常会亮灯，举办各种活动。\n\n话说，你知道“momiji”和“momiji（枫）”有什么区别吗？这两个词经常互换使用，但实际上它们的含义不同。\n\n“秋叶”是指秋季树叶变红变黄的自然现象。这个词通常用来指各种树木的颜色，不仅包括枫树，还包括银杏树、橡树和山毛榉树。', E'["https://resources.matcha-jp.com/resize/720x2000/2025/07/07-238244.webp","https://resources.matcha-jp.com/resize/720x2000/2025/07/03-238115.webp","https://resources.matcha-jp.com/resize/720x2000/2025/07/03-238116.webp","https://resources.matcha-jp.com/resize/720x2000/2025/07/03-238117.webp"]'::jsonb, E'2025-07-07'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/6567', E'zh-Hans', 15, E'【新泻】搭乘世界最快速的艺术观赏列车～享受当地艺术景点与美食', E'新泻县近年来由于大地艺术祭的举办，吸引了世界各地大批艺术爱好者造访，也让新泻成为2018年最潮的艺术之城。这里推荐大家使用不限搭乘次数的“JR东日本铁路周游券”带，大家踩点新泻的人气艺术景点与大啖极品美食。\n\n新泻除了是日本著名的米仓之外，也是新旧艺术交融的重要据点之一。以展示新泻当地艺术家作品为主的新泻市立美术馆，以及收罗了来自世界各地艺术家作品的越后妻有里山现代美术馆“KINARE”，都是近年来新泻必访的艺术景点。\n\n本次我们将从新泻站出发。从东京站搭乘新干线至新泻站约2小时。文中将重点向大家介绍在利用“JR东日本铁路周游券(长野、新泻地区)”来畅游新泻县的人，如何踩点新泻的艺术景点与美食店家。\n\n想要前往新泻市内各个人气观光景点，建议搭乘从新泻站出发的新泻市观光循环公交。若持有大型行李的话，建议将行李寄放在站内的寄物柜。准备完毕之后，就开始艺术熏陶之旅吧！', E'["https://resources.matcha-jp.com/resize/720x2000/2018/10/09-64383.webp","https://resources.matcha-jp.com/resize/720x2000/2018/10/09-64396.webp","https://resources.matcha-jp.com/resize/720x2000/2018/10/09-64385.webp","https://resources.matcha-jp.com/resize/720x2000/2018/10/09-64386.webp"]'::jsonb, E'2018-11-14'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/6491', E'zh-Hans', 15, E'【新潟】大自然就是美术馆！小编实访大地艺术祭攻略', E'世界最大的艺术祭之一“新潟—越后妻有大地艺术祭”，从2000迄今已迈向第七届。作品也从原本的200多件，新增至今年已超过300件，整个作品遍布的范围超过东京23区，包含十日町，津南，川西，中里，松代，松之山。2018年展期为7/29-9/17，错过又要再等三年!作者实际造访亲身体验提供最实用的攻略！\n\n相信有些人听过濑户内海艺术祭，但您知道其实最一开始的是新潟―越后妻有大地艺术祭吗?小编实地探访后，以较不一样的角度介绍艺术祭的初衷、大地艺术祭独有的魅力等等。在了解活动相关背景后，让您除了观赏展览外，更能理解大自然如何影响新潟这片土地。最后介绍精选的推荐展览点，让您可以在短时间有效率地看完所有最精华的作品!\n\n建议:若在新潟计划停留两天以上，通行证比较划算，只要去几个较大的美术馆(キナーレ、絵本と木の実美术馆等等)，就很容易值回票价。 建议前往方式 ①租车自驾前往 自驾的朋友最好能买地图(100日元)和导览书(1300日元)，因为各个展区的指标通常不太好找。(地图与导览书在各个展览区的服务台都有贩售) ②参加当地旅行团(一天)，报名方法如下表 ③火车(较不建议，当地主要有十日町车站可以去各个小站，但班次非常少，几乎是两小时才一班，较远的展览会无法前往) 官方网站 官方中文网站\n\n通行证护照，内有所有作品的盖章处，每到一个地点可以搜集一个章。高中以下的小朋友可以在各个展览区的柜台索取免费护照', E'["https://resources.matcha-jp.com/resize/720x2000/2018/08/27-61362.webp","https://resources.matcha-jp.com/resize/720x2000/2018/08/27-61363.webp","https://resources.matcha-jp.com/resize/720x2000/2018/08/27-61366.webp","https://resources.matcha-jp.com/resize/720x2000/2018/08/27-61365.webp"]'::jsonb, E'2018-09-21'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/7212', E'zh-Hans', 16, E'【升龙道】名古屋出发！七天范例行程走访北陆人气与私房景点', E'从名古屋中部机场出发，玩遍升龙道，一路北上畅游岐阜、富山、金泽、福井等人气观光地，尽情享用美食，最后在名古屋购物后的满载而归的示范七天行程整理给大家！\n\nMATCHA将为各位带来从名古屋进出，以顺时针玩遍岐阜、富山、石川、福井等四县的七天六夜精品行程、热门景点等，打算前往北陆自由行的朋友们不妨参考看看。\n\n日本中部北陆地区的地形加上能登半岛的形状有如龙头，让人想起龙乘风向天高升的英姿，因此这个观光区被称为“升龙道”。\n\n升龙道由南到北横跨中部地方的爱知县、岐阜县、富山县、石川县，拥有许多的温泉、美丽的自然环境，更因爱知县冈崎市是江户幕府建立者德川家康的出生地，升龙道保有许多以德川家康为首的文化建筑、祭典等，可说是一条能够尽享各种不同日本魅力的观光路线。', E'["https://resources.matcha-jp.com/resize/720x2000/2017/07/18-31446.webp","https://resources.matcha-jp.com/resize/720x2000/2018/05/02-53314.webp","https://resources.matcha-jp.com/resize/720x2000/2019/04/03-74223.webp","https://resources.matcha-jp.com/resize/720x2000/2017/08/31-34865.webp"]'::jsonb, E'2019-04-18'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/4267', E'zh-Hans', 16, E'【富山 砺波市】你吃过郁金香冰淇淋吗？日本最大郁金香盛典攻略', E'郁金香代表春日之花，多半是栽种在学校和家中的花圃，不过在富山县的砺波市有座享誉国际的郁金香四季彩馆，却能让郁金香一年四季绽放，是座充满不可思议的体验型设施，而且还能吃到稀有的郁金香冰淇淋喔。本篇文章小编就要带领大家前进一年之中最热闹的“TULIP FAIR”，看看七百种不同品种、300万株郁金香一同绽放的花香时刻。\n\n砺波市是全日本唯一大面积种植郁金香的地区，其实以产业价值来说，花期跟樱花一般大约仅能维持一到两周的花蕊，并非重点，而是埋在土里的球根才有经济价值。但是经过四季彩馆认真研发与规划后，TULIP FAIR每年都有超过30万人以上造访，此会场面积广为3个东京巨蛋大小区域中，总共种植了七百种不同品种、300万株郁金香，花型、香气皆有极大差异，真的是让人大开眼界。\n\n祭典开展期间为2018年4月20到5月5日，期间完全没有休息，开园时间从早上八点半开始一直延续到黄昏的17点30分。成人入场券1000日元、小孩300日元，还有送特别小礼物哦。 接着就带领大家一同前往展区中必看的重要之处。\n\n照片提供：郁金香四季彩馆 从JR砺波站步行过来的话，最先会看到的就是此区用多量郁金香所营造出的造景。其中以立山黑部阿尔卑斯山脉路线的“雪之大谷”为概念设计，高达4公尺的拱廊，共有约2万5,000株郁金香在此绽放，相当壮观。', E'["https://resources.matcha-jp.com/resize/720x2000/2017/04/06-23459.webp","https://resources.matcha-jp.com/resize/720x2000/2017/04/06-23458.webp","https://resources.matcha-jp.com/resize/720x2000/2017/04/06-23461.webp","https://resources.matcha-jp.com/resize/720x2000/2017/04/06-23462.webp"]'::jsonb, E'2018-03-20'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/4171', E'zh-Hans', 16, E'『富山县 南砺市』日本列岛最后一个秘境：庄川峡乘船赏樱', E'庄川峡位在日本北陆自然景观非常丰富的富山县，距离著名的世界文化遗产合掌村中相仓合掌村集落及菅沼合掌村集落约45分钟车程，距离有日本阿尔卑斯山之称的立山黑部则约90分钟车程，今春不如放慢脚步来日本列岛的最后一个秘境享受大牧温泉、看樱花。\n\n相信身为日本通的读者一定可以立马数出几个知名游船特色地区，包含松岛观光船、漩涡鸣门游览船等等，其实光是搭船欣赏景色本身就已经相当引人入胜，若是再加上一、两个绝景做为话题的话，更是让人哪怕千里之遥，也是要亲身前往，而位于五个山县立自然公园内的庄川峡县定公园正是一例。\n\n图片提供：庄川游覧船株式会社 庄川峡游船的特点就是一整条河岸仅有一家公司经营船班，当船行驶出港后，船上人们就像是只身前往绝美境界般可独享船身飘荡在高低峡谷之间的绝美景色。 沿途随着光影变化，水面色泽、倒影犹如名画家的调色盘一直不停调整，时而还有飞鸟划破这一抹宁静。\n\n图片提供：庄川游覧船株式会社 若逢春天来访，此处的樱花景色更是堪称一绝。散策赏樱已不稀奇，若是能随着游船在平静的水面上缓缓驶过，一路配着壮丽山岳，欣赏点缀于林谷间的点点粉红，此般遗世独立的景象，真的叫人好不感动。', E'["https://resources.matcha-jp.com/resize/720x2000/2017/03/15-21334.webp","https://resources.matcha-jp.com/resize/720x2000/2017/03/15-21332.webp","https://resources.matcha-jp.com/resize/720x2000/2017/03/15-21335.webp","https://resources.matcha-jp.com/resize/720x2000/2017/03/15-21337.webp"]'::jsonb, E'2018-04-05'::timestamptz, null, null, null),
(E'https://matcha-jp.com/cn/1109', E'zh-Hans', 17, E'金泽车站的建筑魅力！为您介绍“鼓门”和“迎客圆顶”的理念！', E'金泽车站的“鼓门”和“迎客圆顶”的理念含义是什么呢？本篇将为您介绍它们和历史的关联以及巧妙的设计！\n\n石川县，至今还保留着古城风情，是一个能体验古日本的地方。不仅有温泉街，面海的地方还能品尝到海鮮。对于日本人来说，也是一个充满魅力的县市。 其中又以金泽市最多看点，保留了当时许多的特色。例如在金泽城、兼六园和武家屋敷或茶屋街等。\n\n在前往这些景点时，通常会从金泽车站出发。不过您知道金泽车站本身就是一个很大的景点吗？\n\n这个鼓门的高度有13.7公尺，以两根大柱子所支撑。它的理念来自传统艺术“能乐・加贺宝生”当中的鼓为灵感。', E'["https://resources.matcha-jp.com/resize/720x2000/2022/02/25-123246.webp","https://resources.matcha-jp.com/resize/720x2000/2022/02/25-123247.webp","https://resources.matcha-jp.com/resize/720x2000/2022/02/25-123249.webp","https://resources.matcha-jp.com/resize/720x2000/2022/02/25-123248.webp"]'::jsonb, E'2017-05-05'::timestamptz, null, null, null)
